Rules.InvariantScript:
// ✅ Vérifier les champs requis
If(
    IsBlank(Txt_CarName_1.Text) || IsBlank(Txt_CarID_1.Text),

    // ❌ Champs obligatoires manquants
    UpdateContext({ ShowError: true })
,
    // ✅ Champs valides : procéder
    UpdateContext({
        ShowError: false,
        ShowLoader: true
    });

    // ✅ Patch : ajout ou mise à jour
    Set(
        PatchedItem15,
        Patch(
            'Booking pCars List',
            If(IsBlank(varItemToEdit3), Defaults('Booking pCars List'), varItemToEdit3),
            {
                Title: Txt_CarName_1.Text,
                CarID: Value(Txt_CarID_1.Text),
                CarStatus: {
                    '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedReference",
                    Value: "Active"
                },
                CarAddedDate: Today()
            }
        )
    );
    // Recharge complètement l’élément patché avec les pièces jointes
Set(varItemToEdit3, LookUp('Booking pCars List', ID = PatchedItem15.ID)),

    // ✅ Soumettre les pièces jointes si le patch a réussi
    If(
        !IsBlank(PatchedItem15) && !IsError(PatchedItem15),
        AttachmentForm_1.LastSubmit.ID = PatchedItem15.ID;
        SubmitForm(AttachmentForm_1);
    );

    // ✅ Nettoyer les champs
    Reset(Txt_CarName_1);
    Reset(Txt_CarID_1);
    Reset(AddAttachment_1);

    // ✅ Mettre à jour le contexte
    UpdateContext({
        SuccessMessage: "Booking information successfully saved.",
        ShowLoader: false,
        AddCarPopup: false
    });

    // ✅ Réinitialiser varItemToEditPCar pour différencier Add/Update
    Set(varItemToEdit3, Blank());

    // ✅ Recharger la collection
    ClearCollect(BookingpCarCollection, 'Booking pCars List')
)

If(
    Not(IsBlank(LookUp(SelectedBookingCarStatus, Value = ThisItem.Value))),
    // Item is already in the new collection, so remove it
    Remove(
        SelectedBookingCarStatus,
        LookUp(SelectedBookingCarStatus, Value = ThisItem.Value)
    );
    ,
    // Item is not in the new collection, so add it
    Collect(
        SelectedBookingCarStatus,
        ThisItem
    )
)

If(
    Not(IsBlank(LookUp(SelectedBookingCarStatus, Value = ThisItem.Value))),
    // Item is selected
    If(
        ThisItem.Value = "Active",
        RGBA(48, 194, 27, 1), // Color for "Booked"
        If(
            ThisItem.Value = "Maintenance",
            RGBA(251, 25, 25, 1), // Color for "Cancelled"
            Parent.Fill // Default color if the status is neither "Booked" nor "Cancelled"
        )
    ),
    // Item is not selected
    RGBA(44, 44, 44, 1) // Default color when not selected
)

//Clear All Filter
Reset(TxtFilterCarname_1);           //carname
Reset(TxtFilterCarID_1);            //CarID
Reset(DatePickerDateAddedFrom_1);  //DateAddedFrom
Reset(DatePickerDateAddedTo_1);   //DateAddedTo
Reset(Dropdown1_1);
Refresh('Booking pCars List');
